-- Generated by scripts/prospectus_2025/build_catalog.py. Do not edit by hand.
-- Applies the 2025 prospectus to the course catalogue. Needs migration 027.
-- Run it in one go: it is one transaction, so nothing changes if any step fails.
-- Safe to run twice; the second run changes nothing.

BEGIN;

-- Stop if migration 027 has not been run
DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name = 'courses' AND column_name = 'curriculum') THEN RAISE EXCEPTION 'Run migrations/027_course_catalog_2025.sql first'; END IF; END $$;

-- Course descriptions, each stored once and referred to by number below
CREATE TEMP TABLE _desc (desc_id INT PRIMARY KEY, body TEXT) ON COMMIT DROP;

-- 1. Courses in both plans: new code, name and semester; old values kept
CREATE TEMP TABLE _catalog_2025 (course_id INT, from_code TEXT, code TEXT, name TEXT, semester INT,
  old_code TEXT, old_name TEXT, old_semester INT, credit_hours INT, prereq TEXT, desc_id INT) ON COMMIT DROP;

-- Only rows still exactly as they were when the plan was built (first run)
DELETE FROM _catalog_2025 t WHERE NOT EXISTS (
  SELECT 1 FROM courses c WHERE c.course_id = t.course_id AND c.code = t.from_code AND c.curriculum = 'both' AND c.old_code IS NULL AND c.old_name IS NULL AND c.old_semester IS NULL);
-- Free the codes first so two courses can swap codes (CS221 / CS222)
UPDATE courses c SET code = '~' || c.course_id FROM _catalog_2025 t WHERE c.course_id = t.course_id AND t.old_code IS NOT NULL;
UPDATE courses c SET code = t.code, name = t.name, semester = t.semester, year = (t.semester + 1) / 2,
       old_code = t.old_code, old_name = t.old_name, old_semester = t.old_semester,
       credit_hours = t.credit_hours, prereq = t.prereq, curriculum = 'both',
       description = (SELECT body FROM _desc WHERE desc_id = t.desc_id)
  FROM _catalog_2025 t WHERE c.course_id = t.course_id;

-- 2. Courses only earlier batches take
UPDATE courses c SET curriculum = 'old', credit_hours = COALESCE(c.credit_hours, v.ch),
       description = COALESCE(c.description, (SELECT body FROM _desc WHERE desc_id = v.desc_id))
