-- 5. Uploads: move the ones whose code now belongs to a different course.
--    Each move is recorded in files_course_code_backup_027 so it can be undone.
CREATE TABLE IF NOT EXISTS files_course_code_backup_027 (file_id INT PRIMARY KEY, old_course_code TEXT, new_course_code TEXT, moved_at TIMESTAMPTZ DEFAULT NOW());
CREATE TEMP TABLE _upload_moves (from_code TEXT, to_code TEXT) ON COMMIT DROP;
-- Only on the first run: later uploads under these codes are for the new course.
-- Skips any move that would clash with an upload of the same title.
CREATE TABLE IF NOT EXISTS catalog_2025_applied (applied_at TIMESTAMPTZ DEFAULT NOW());
SELECT f.file_id, f.course_code, m.to_code FROM files f JOIN _upload_moves m ON f.course_code = m.from_code
 WHERE NOT EXISTS (SELECT 1 FROM catalog_2025_applied)
   AND NOT EXISTS (SELECT 1 FROM files_course_code_backup_027 b WHERE b.file_id = f.file_id)
   AND NOT EXISTS (SELECT 1 FROM files g WHERE g.course_code = m.to_code AND g.title = f.title
                   AND g.category_id IS NOT DISTINCT FROM f.category_id AND g.instructor_id IS NOT DISTINCT FROM f.instructor_id);
UPDATE files f SET course_code = b.new_course_code FROM files_course_code_backup_027 b
 WHERE f.file_id = b.file_id AND f.course_code = b.old_course_code;
-- Links that pointed at a moved code meant the old course, so they follow it
SELECT CASE WHEN l.course_code_1 = m.from_code THEN m.to_code ELSE l.course_code_1 END,
       CASE WHEN l.course_code_2 = m.from_code THEN m.to_code ELSE l.course_code_2 END
  FROM manual_course_links l JOIN _upload_moves m ON m.from_code IN (l.course_code_1, l.course_code_2)
 WHERE NOT EXISTS (SELECT 1 FROM catalog_2025_applied)
ON CONFLICT DO NOTHING;
DELETE FROM manual_course_links l USING _upload_moves m
 WHERE m.from_code IN (l.course_code_1, l.course_code_2) AND NOT EXISTS (SELECT 1 FROM catalog_2025_applied);

-- 6. Link each old code to its new code so the course shows uploads under both
ON CONFLICT DO NOTHING;


-- 7. What changed
SELECT curriculum, COUNT(*) AS courses, COUNT(old_code) AS with_old_code, COUNT(description) AS with_description
  FROM courses GROUP BY curriculum ORDER BY curriculum;

COMMIT;
